export default function route({ ticket, ticketId, fieldId, comment }) {
  if (ticket?.id !== ticketId || !Array.isArray(ticket?.raw?.custom_fields))
    throw Error("Ticket ID or custom fields invalid");
  const matches = ticket.raw.custom_fields.filter((x) => x?.id === fieldId);
  if (matches.length !== 1) throw Error("Configured GitHub issue field is absent or duplicated");
  const value = matches[0].value;
  if (value == null || value === "") {
    if (typeof ticket.subject !== "string" || !ticket.subject.trim())
      throw Error("Ticket subject is missing");
    return { existing: false, issueNumber: 1, title: ticket.subject, comment: "-" };
  }
  const text = String(value);
  if (!/^\d+$/.test(text) || !Number.isSafeInteger(Number(text)) || Number(text) < 1)
    throw Error("Invalid stored GitHub issue number");
  if (!comment.trim()) throw Error("A comment is required for an existing issue");
  return { existing: true, issueNumber: Number(text), title: ticket.subject || "-", comment };
}

