export default async function update({ ticketId, fieldId, issue }, context) {
  if (!Number.isSafeInteger(issue?.number) || issue.number < 1)
    throw Error("Created issue has no number");
  return await context.actions.call("zendesk.update_ticket", {
    ticketId,
    customFields: [{ id: fieldId, value: issue.number }],
  });
}
